/** 그룹 id → scope 조회용 */
export const GROUP_SCOPE: Record<DirectoryGroupId, DirectoryScope> = DIRECTORY_GROUPS.reduce(
  (acc, group) => {
    acc[group.id] = group.scope;
    return acc;
  },
  {} as Record<DirectoryGroupId, DirectoryScope>
);

/** 사이트에 scope가 없으면 소속 그룹의 scope를 따른다 */
export function scopeOf(site: DirectorySite): DirectoryScope {
  return site.scope ?? GROUP_SCOPE[site.group];
}

