/** 국내 + 해외(주제별) + 해외(국가별) + 트래픽 보강 + 유머·밈 전체 */
export const DIRECTORY_SITES: DirectorySite[] = [
  ...KR_DIRECTORY_SITES,
  ...GLOBAL_DIRECTORY_SITES,
  ...WORLD_DIRECTORY_SITES,
  ...WORLD_EXTRA_SITES,
  ...HUMOR_DIRECTORY_SITES,
];

/**
 * 그룹 id → 사이트 배열.
 * 그룹은 DIRECTORY_GROUPS 순서(카테고리 인기순), 사이트는 rank 순으로 나온다.
 */
export function groupDirectorySites(sites: DirectorySite[] = DIRECTORY_SITES) {
  const byGroup = new Map<DirectoryGroupId, DirectorySite[]>();
  for (const site of sites) {
    const bucket = byGroup.get(site.group);
    if (bucket) bucket.push(site);
    else byGroup.set(site.group, [site]);
  }
  return DIRECTORY_GROUPS.filter(g => byGroup.has(g.id)).map(group => ({
    group,
    sites: byGroup.get(group.id)!.sort((a, b) => a.rank - b.rank),
  }));
}
